components.css:
.ds-btn-primary { background: var(--color-primary, #6e56cf); color: #fff; font-family: var(--font-ui,'Plus Jakarta Sans','Segoe UI',system-ui,sans-serif);
border: none; border-radius: 8px; padding: 6px 12px; font-size: 12px; font-weight: 600; cursor: pointer;
box-shadow: 0 6px 16px -10px rgb(48 36 100 / .4); transition: filter .15s, background-color .15s; }
.ds-btn-primary:hover { filter: brightness(1.1); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--color-primary, #6e56cf); outline-offset: 2px; }
.ds-btn-primary:disabled { opacity: .6; }

.ds-btn-glass { background: var(--color-glass-strong, rgb(255 255 255 / .88)); color: var(--color-ink, #17151f);
font-family: var(--font-ui,'Plus Jakarta Sans','Segoe UI',system-ui,sans-serif); border: 1px solid var(--color-hairline, rgb(255 255 255 / .78)); border-radius: 8px;
padding: 6px 12px; font-size: 12px; font-weight: 600; cursor: pointer; transition: background-color .15s; }
.ds-btn-glass:hover { background: var(--color-hover-glass, rgb(110 86 207 / .07)); }
.ds-btn-glass:focus-visible { outline: 2px solid var(--color-primary, #6e56cf); outline-offset: 2px; }

.ds-btn-danger { background: rgb(213 83 94 / .15); color: var(--color-danger-ink, #c23a55);
font-family: var(--font-ui,'Plus Jakarta Sans','Segoe UI',system-ui,sans-serif); border: 1px solid rgb(213 83 94 / .3); border-radius: 8px; padding: 6px 12px;
font-size: 12px; font-weight: 600; cursor: pointer; transition: background-color .15s; }
.ds-btn-danger:hover { background: rgb(213 83 94 / .25); }
.ds-btn-danger:focus-visible { outline: 2px solid var(--color-danger, #d5535e); outline-offset: 2px; }

.ds-pill-current { display: inline-flex; align-items: center; gap: 4px; height: 20px; padding: 0 8px;
border-radius: 9999px; background: var(--color-lane-1, #6e56cf); color: var(--color-surface, #ffffff);
font-family: var(--font-ui,'Plus Jakarta Sans','Segoe UI',system-ui,sans-serif); font-size: 10.5px; line-height: 1; font-weight: 700; white-space: nowrap; }

.ds-pill-outline { display: inline-flex; align-items: center; gap: 4px; height: 20px; padding: 0 8px;
border-radius: 9999px; border: 1.5px solid var(--color-lane-1, #6e56cf); background: transparent;
color: color-mix(in oklab, var(--color-lane-1, #6e56cf), var(--color-ink, #17151f) 55%);
font-family: var(--font-ui,'Plus Jakarta Sans','Segoe UI',system-ui,sans-serif); font-size: 10.5px; line-height: 1; font-weight: 600; white-space: nowrap; }

.ds-toggle { position: relative; display: inline-flex; align-items: center; width: 40px; height: 22px;
border-radius: 9999px; border: 1px solid var(--color-hairline, rgb(255 255 255 / .78));
background: rgb(23 21 31 / .15); cursor: pointer; transition: background-color .15s; }
.ds-toggle-on { background: var(--color-primary, #6e56cf); }
.ds-toggle-knob { position: absolute; left: 2px; width: 18px; height: 18px; border-radius: 9999px;
background: #fff; box-shadow: 0 6px 16px -10px rgb(48 36 100 / .4); transition: transform .15s; }
.ds-toggle-on .ds-toggle-knob { transform: translateX(18px); }
.ds-toggle:focus-visible { outline: 2px solid var(--color-primary, #6e56cf); outline-offset: 2px; }

.ds-cube { display: inline-grid; width: 18px; height: 18px; place-items: center; border-radius: 4px;
background: rgb(224 162 75 / .15); color: var(--color-warning-ink, #8a5a11); font-family: var(--font-mono,'JetBrains Mono',Consolas,monospace);
font-size: 10.5px; font-weight: 700; }

.ds-panel { background: var(--color-glass, rgb(255 255 255 / .76)); border: 1px solid var(--color-hairline, rgb(255 255 255 / .78));
border-radius: 16px; padding: 16px; box-shadow: inset 0 1px 0 0 rgb(255 255 255 / .85), 0 14px 34px -26px rgb(48 36 100 / .45);
backdrop-filter: blur(24px); -webkit-backdrop-filter: blur(24px);
display: flex; flex-direction: column; gap: 8px; font-family: var(--font-ui,'Plus Jakarta Sans','Segoe UI',system-ui,sans-serif); }
.ds-panel-title { font-size: 16px; font-weight: 700; letter-spacing: -.01em; color: var(--color-ink, #17151f); }
.ds-panel-body { font-size: 12.5px; line-height: 1.5; color: var(--color-ink-soft, #413d51); }
